-- Table documents
DROP TABLE IF EXISTS `documents_restauration_test`;
CREATE TABLE `documents_restauration_test` (
  `id_interne` varchar(20) NOT NULL,
  `titre` varchar(500) NOT NULL,
  `chemin_drive` varchar(500) NOT NULL,
  `dossier_parent` varchar(200) NOT NULL,
  `type_fichier` varchar(100) NOT NULL,
  `id_drive` varchar(100) NOT NULL,
  `lien_drive` varchar(500) NOT NULL,
  `date_modification` varchar(50) NOT NULL,
  `taille_octets` bigint(20) DEFAULT NULL,
  `categorie` varchar(200) NOT NULL,
  `contenu_fichier_local` varchar(200) DEFAULT NULL,
  `statut_import` varchar(50) NOT NULL,
  `anomalie` text NOT NULL,
  `doublon_info` text DEFAULT NULL,
  PRIMARY KEY (`id_interne`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


-- Table categories
DROP TABLE IF EXISTS `categories_restauration_test`;
CREATE TABLE `categories_restauration_test` (
  `slug` varchar(50) NOT NULL,
  `nom` varchar(100) NOT NULL,
  `ordre` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


-- Table document_categories
DROP TABLE IF EXISTS `document_categories_restauration_test`;
CREATE TABLE `document_categories_restauration_test` (
  `id_interne` varchar(20) NOT NULL,
  `categorie_slug` varchar(50) NOT NULL,
  PRIMARY KEY (`id_interne`,`categorie_slug`),
  KEY `categorie_slug` (`categorie_slug`),
  CONSTRAINT `document_categories_ibfk_1` FOREIGN KEY (`id_interne`) REFERENCES `documents` (`id_interne`),
  CONSTRAINT `document_categories_ibfk_2` FOREIGN KEY (`categorie_slug`) REFERENCES `categories` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


-- Table series
DROP TABLE IF EXISTS `series_restauration_test`;
CREATE TABLE `series_restauration_test` (
  `id` varchar(50) NOT NULL,
  `nom` varchar(200) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


-- Table document_series
DROP TABLE IF EXISTS `document_series_restauration_test`;
CREATE TABLE `document_series_restauration_test` (
  `id_interne` varchar(20) NOT NULL,
  `serie_id` varchar(50) NOT NULL,
  `position` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id_interne`,`serie_id`),
  KEY `serie_id` (`serie_id`),
  CONSTRAINT `document_series_ibfk_1` FOREIGN KEY (`id_interne`) REFERENCES `documents` (`id_interne`),
  CONSTRAINT `document_series_ibfk_2` FOREIGN KEY (`serie_id`) REFERENCES `series` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


-- Table soumissions
DROP TABLE IF EXISTS `soumissions_restauration_test`;
CREATE TABLE `soumissions_restauration_test` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `auteur_nom` varchar(200) NOT NULL,
  `titre` varchar(500) NOT NULL,
  `contenu` text NOT NULL,
  `email` varchar(255) NOT NULL,
  `declaration_autorisation` tinyint(1) NOT NULL DEFAULT 0,
  `statut` enum('a_valider','publie','refuse') NOT NULL DEFAULT 'a_valider',
  `date_soumission` datetime NOT NULL DEFAULT current_timestamp(),
  `date_traitement` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


